			/**
			 * 게시글 상세 화면 데이터 전달 및 화면 구성정보 전달
			 ** @param {"CREATE" | "READ"} psType 게시글 상세 조회 타입
			 */
			function setDtlType(psType) {
			    var vcEmbDtl = app.lookup("embDtl");
			    var voDsBoardList = app.lookup("dsList");
			    var voDmDtlParam = app.lookup("dmDtlParam");
			    
			    if (psType == "BOARDCREATE") { // 신규
			//        console.log("list2222");
			        var voUserNm = util.Auth.getUserInfo(app, "USER_NM");
			        voDmDtlParam.setValue("WRTR_NM_ENCPT", voUserNm);
			        voDmDtlParam.setValue("NUM", 1);
			        voDmDtlParam.setValue("FRST_REG_DT", util.DataMap.getValue(app, "dmLogin", "strToday"));
			        voDmDtlParam.setValue("BRTH_YMD", util.DataMap.getValue(app, "dmLogin", "loginBir"));
			        voDmDtlParam.setValue("SXDC_SE_CD", util.DataMap.getValue(app, "dmLogin", "loginGen"));
			        voDmDtlParam.setValue("CNTN_IP_ADDR", util.DataMap.getValue(app, "dmLogin", "loginIp"));
			        voDmDtlParam.setValue("EML_ADDR_ENCPT", util.DataMap.getValue(app, "dmLogin", "loginEmail"));
			        
			    }else{
			        if(psType== 'BORDREAD'){
			            var vnRowIdx = util.Grid.getIndex(app, "grdBoardList");
			//            voDmDtlParam.setValue("BBSCTT_TTL_NM", voDsBoardList.getValue(vnRowIdx, "BBSCTT_TTL_NM"));
			            voDmDtlParam.setValue("BBSCTT_ESNTAL_NO", voDsBoardList.getValue(vnRowIdx, "BBSCTT_ESNTAL_NO"));
			            voDmDtlParam.setValue("NUM", voDsBoardList.getValue(vnRowIdx, "NUM"));            
			        }else{
			            console.log("RPLYREAD22222");
			            var vnRowIdx = util.Grid.getIndex(app, "grdBoardList");
			            voDmDtlParam.setValue("RETE_ESNTAL_NO", voDsBoardList.getValue(vnRowIdx, "RETE_ESNTAL_NO"));
			            voDmDtlParam.setValue("BBSCTT_ESNTAL_NO", voDsBoardList.getValue(vnRowIdx, "BBSCTT_ESNTAL_NO"));
			            voDmDtlParam.setValue("NUM", voDsBoardList.getValue(vnRowIdx, "NUM"));
			            console.log("답글NO"+voDsBoardList.getValue(vnRowIdx, "RETE_ESNTAL_NO"));  
			        }
			    }
			    // 상세화면의 함수를 호출하여 데이터 전달
			    vcEmbDtl.ready(function() {
			        var voEmbApp = vcEmbDtl.getEmbeddedAppInstance();
			        if (voEmbApp.hasAppMethod("setDtlData")) {
			            voEmbApp.callAppMethod("setDtlData", psType, voDmDtlParam.getDatas());
			        }
			    });
			    
			    // 게시판 작성 탭 이동
			    selectMdiItem(2);
			}

